export class SessionClient {
  async login(url: string): Promise<Response> {
    const res = await fetch(url);
    if (!res.ok) {
      throw new Error("login failed for " + url);
    }
    return res;
  }
}

export function buildLoginUrl(base: string, accessToken: string): string {
  return base + "/session?access_token=" + encodeURIComponent(accessToken);
}

