import { SessionClient, buildLoginUrl } from "./session-client";

export async function handleLogin(base: string, token: string, log: { error(m: string): void }) {
  try {
    await new SessionClient().login(buildLoginUrl(base, token));
  } catch (err) {
    log.error((err as Error).message);
  }
}
